with ins as (insert into public.artist_eras (artist_slug,from_year,to_year,sound,tags,source_url,source_name,palette) select x.s,x.f,x.t,x.snd,array(select json_array_elements_text(x.tags)),x.u,x.n,x.p from json_to_recordset('[{"s":"og-shez","f":2026,"t":null,"snd":"Desi hip-hop, Jersey club, dubstep and experimental edits","tags":["Desi hip-hop","Jersey club","dubstep","electro","edits"],"u":"https://www.thewildcity.com/mixes/21685-wild-city-261-og-shez","n":"Wild City","p":"night"},{"s":"rasa","f":2022,"t":null,"snd":"Dark, high-energy bass sets for boogie or mosh","tags":["bass","dark","high-energy"],"u":"https://mixmag.asia/read/mma-radio-bass-queen-rasa-exclusive-mixes","n":"Mixmag Asia","p":"night"},{"s":"big-m","f":2026,"t":null,"snd":"Slick UKG and housey steppers","tags":["UKG","house","steppers","bass"],"u":"https://ra.co/news/84537","n":"Resident Advisor","p":"night"},{"s":"bindas","f":2026,"t":null,"snd":"Afro Desi edits, Baile, UK Funky and UKG","tags":["afro desi","baile","uk funky","ukg","global bass"],"u":"https://soundcloud.com/new-delhi-community-radio/ndcr-mix-final-bindas","n":"New Delhi Community Radio","p":"blush"}]'::json) as x(s text,f int,t int,snd text,tags json,u text,n text,p text) join public.artists a on a.slug=x.s where not exists (select 1 from public.artist_eras e where e.artist_slug=x.s and e.from_year=x.f) returning 1) select count(*) from ins;